theorem isTopologicalBasis_isClopen_of_compact_t2_totallyDisconnected {X : Type w}
    [TopologicalSpace X] [CompactSpace X] [T2Space X] [TotallyDisconnectedSpace X] :
    TopologicalSpace.IsTopologicalBasis {s : Set X | IsClopen s}

theorem closedSubgroup_eq_sInf_open [CompactSpace G] [TotallyDisconnectedSpace G]
    (H : ClosedSubgroup G) :
    (H : Subgroup G) = sInf {N : Subgroup G | IsOpen (N : Set G) ∧ (H : Subgroup G) ≤ N}

theorem directed_finset_has_lower_bound {α : Type*} {ι : Type*} {U : ι → Set α}
    (hdir : Directed (· ⊇ ·) U) :
    ∀ s : Finset ι, s.Nonempty → ∃ k : ι, ∀ i ∈ s, U k ⊆ U i

theorem exists_mem_of_not_le {G : Type u} [Group G] [TopologicalSpace G] {K L : ClosedSubgroup G}
    (hnotle : ¬ (L : Subgroup G) ≤ (K : Subgroup G)) :
    ∃ x : G, x ∈ (L : Subgroup G) ∧ x ∉ (K : Subgroup G)

theorem exists_le_adjoin_singleton [Algebra.IsSeparable k K]
    (B' : Subalgebra k Ω) (hB' : B' ≤ fb.range) [Module.Finite k B'] :
    ∃ β : K, B' ≤ Algebra.adjoin k {fb β}

theorem autHomOfCompIso_conj_eq_one_of_eq_one
    (H : C ⥤ C') {F G : C' ⥤ FintypeCat.{w}}
    {F₀ G₀ : C ⥤ FintypeCat.{w}}
    (t : F ≅ G) (s : H ⋙ F ≅ F₀) (r : H ⋙ G ≅ G₀)
    (a : Aut F) (ha : autHomOfCompIso H s a = 1) :
    autHomOfCompIso H r (continuousConjAut t a) = 1

